<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
use App\Core\{Config,Db,Problem};
use App\Domain\{Accounts,Catalog,ConsumerFood,FoodData,FoodDate,DigitalLink,ConsumerAssets};
$cfg=oa_test_config();
if(!str_contains($cfg['db']['dsn'],'dbname=openaliment_tests;'))throw new RuntimeException('Consumer tests require isolated openaliment_tests.');
Config::load($cfg);if(Db::one('SELECT DATABASE() AS name')['name']!=='openaliment_tests')throw new RuntimeException('Wrong database.');
$checks=[];
set_error_handler(static function(int $severity,string $message,string $file,int $line):never{throw new ErrorException($message,0,$severity,$file,$line);});
function ok(string $name,bool $condition):void{global$checks;$checks[]=['name'=>$name,'passed'=>$condition];if(!$condition)throw new RuntimeException('FAIL '.$name);echo 'PASS '.$name.PHP_EOL;}
function bad(string $name,callable $fn,int $status=422):void{try{$fn();}catch(Problem $e){ok($name,$e->status===$status);return;}throw new RuntimeException('Expected rejection: '.$name);}
$food=FoodData::unknown();ok('Unknown facts do not become zeros',FoodData::validate($food)['nutrition']['values']===null);
$food['allergens']=['status'=>'declared','contains'=>['milk'],'may_contain'=>['nuts']];
$food['nutrition']=['status'=>'declared','basis'=>'per_100_g','preparation'=>'as_sold','jurisdiction'=>'EU','values'=>['carbohydrate_g'=>4.2,'sugars_g'=>4.0,'fat_g'=>3.5],'portion'=>['amount'=>200,'unit'=>'g']];
$food['after_opening']=['hours'=>48,'conditions'=>'Păstrat la 2–4 °C, în ambalaj închis.'];
ok('Structured food declarations accepted',FoodData::validate($food)['allergens']['contains']===['milk']);
$invalid=$food;$invalid['allergens']['status']='unknown';bad('Unknown declaration cannot hide listed allergens',fn()=>FoodData::validate($invalid));
$invalid=$food;$invalid['allergens']['may_contain']=['milk'];bad('Contains and may contain cannot overlap',fn()=>FoodData::validate($invalid));
$invalid=$food;$invalid['allergens']['contains']=['unrecognized'];bad('Unknown allergen codes rejected',fn()=>FoodData::validate($invalid));
$invalid=$food;$invalid['nutrition']['values']['sugars_g']=6;bad('Sugar above total carbohydrate rejected',fn()=>FoodData::validate($invalid));
$invalid=$food;$invalid['nutrition']['values']['carbohydrate_g']='4.2';bad('Numeric strings are not nutrition facts',fn()=>FoodData::validate($invalid));
$invalid=$food;$invalid['nutrition']['values']['carbohydrate_g']=INF;bad('Infinite nutrition values rejected',fn()=>FoodData::validate($invalid));
$invalid=$food;$invalid['nutrition']['values']['secret_field']=12;bad('Unknown structured fields rejected',fn()=>FoodData::validate($invalid));
$invalid=$food;$invalid['after_opening']['hours']=0;bad('Zero opening duration rejected',fn()=>FoodData::validate($invalid));
$portion=$food;$portion['nutrition']['basis']='per_portion';$portion['nutrition']['values']['carbohydrate_g']=150;$portion['nutrition']['values']['sugars_g']=10;
ok('Large valid portions are not constrained to 100 g',FoodData::validate($portion)['nutrition']['values']['carbohydrate_g']===150.0);
$volume=$food;$volume['nutrition']['basis']='per_100_ml';$volume['nutrition']['values']['carbohydrate_g']=120;ok('Mass per 100 ml is not confused with mass per 100 g',FoodData::validate($volume)['nutrition']['values']['carbohydrate_g']===120.0);
bad('Unconfirmed form allergens rejected',fn()=>FoodData::fromForm(['food_contains'=>['milk']]));
ok('Comma decimal form normalized',FoodData::fromForm(['food_carbohydrate_g'=>'4,2'])['nutrition']['values']['carbohydrate_g']===4.2);
bad('Malformed portion rejected',fn()=>FoodData::fromForm(['food_carbohydrate_g'=>'4','food_portion_amount'=>'2oops']));
ok('GS1 00 day preserves month precision',FoodDate::gs1('280200','best_before',2026)['value']==='2028-02');
ok('GS1 year uses 49 past / 50 future window',FoodDate::gs1('250101','use_by',2075)['value']==='2125-01-01');
bad('Invalid leap date rejected',fn()=>FoodDate::gs1('270229','use_by',2026));
bad('Month 00 rejected',fn()=>FoodDate::gs1('260015','best_before',2026));
bad('Calendar rollover rejected',fn()=>FoodDate::validate(['kind'=>'use_by','value'=>'2026-02-31','precision'=>'day','source'=>'user']));
bad('Precision mismatch rejected',fn()=>FoodDate::validate(['kind'=>'best_before','value'=>'2026-02-28','precision'=>'month','source'=>'user']));
ok('EAN converts to a normalized GTIN',ConsumerFood::code('9520000000011')['gtin14']==='09520000000011');
bad('Invalid numeric demo suggestion rejected',fn()=>ConsumerFood::code('1111111111111'));
ok('External GS1 stem and plus lot preserved',ConsumerFood::code('https://example.org/id/01/09520000000011/10/A%2BB?15=280200')['lot_code']==='A+B');
ok('Slash lot decoded once',ConsumerFood::code('https://example.org/01/09520000000011/10/A%252FB')['lot_code']==='A%2FB');
ok('Consumer scanner accepts official compressed EPC example',ConsumerFood::code('https://example.org/exMBZFlvQMDly-mRqD')['gtin14']==='09528765123457');
bad('Duplicate date parameters rejected',fn()=>ConsumerFood::code('https://example.org/01/09520000000011?17=261101&17=261102'));
bad('Non-HTTPS external data address rejected',fn()=>ConsumerFood::code('http://example.org/01/09520000000011'));
bad('Credentials in URI rejected',fn()=>ConsumerFood::code('https://user:secret@example.org/01/09520000000011'));
$demo=ConsumerFood::lookup('9520000000011');ok('PBT remains a demonstration with unknown facts',$demo['simulation']&&$demo['expiry']===null&&$demo['food_data']['nutrition']['status']==='unknown');
$account=Accounts::register(['email'=>'consumer-fixture-'.Db::id().'@example.invalid','display_name'=>'Fixture consumator','organization'=>'Fixture consumator','password'=>bin2hex(random_bytes(18))],true);
$p=['tenant'=>$account['tenant_id'],'user'=>$account['id'],'role'=>'owner','admin'=>true,'token'=>null];
$product=Catalog::product($p,['name'=>'Iaurt de probă','category'=>'lactate'])['id'];
$base='952'.str_pad((string)random_int(1,999999999),9,'0',STR_PAD_LEFT);$sum=0;for($i=11,$w=3;$i>=0;$i--,$w=4-$w)$sum+=(int)$base[$i]*$w;$gtin=$base.(string)((10-$sum%10)%10);
$item=Catalog::trade($p,$product,['name'=>'200 g','gtin'=>$gtin,'claim_evidence'=>'Fixture isolated, no commercial rights claim.'])['id'];
Db::run("UPDATE trade_items SET gtin_status='verified',verified_at=?,verified_by=? WHERE id=?",[Db::now(),$p['user'],$item]);Db::insert('gtin_registry',['gtin14'=>DigitalLink::gtin($gtin),'tenant_id'=>$p['tenant'],'trade_item_id'=>$item]);
$labelData=['version_key'=>'C1','name'=>'Iaurt de probă','category'=>'lactate','ingredients'=>'Lapte, culturi lactice.','allergens'=>'Conține lapte.','net_quantity'=>'200 g','operator'=>'Fixture, nu operator comercial.','food_data'=>$food];
$label=Catalog::label($p,$item,$labelData)['id'];bad('Draft not exposed by native consumer lookup',fn()=>ConsumerFood::lookup(url('/t/'.$item)),404);
Catalog::publishLabel($p,$label);$lot=Catalog::batch($p,$item,['product_info_version_id'=>$label,'lot_code'=>'C/001+X','use_by'=>'2027-01-10'])['id'];Catalog::publishBatch($p,$lot);
$projection=ConsumerFood::lookup(url('/b/'.$lot));
ok('Non-bread consumer data needs no recipe',$projection['name']==='Iaurt de probă'&&!array_key_exists('recipe',$projection));
ok('Only approved structured facts exposed',$projection['food_data']['allergens']['contains']===['milk']&&$projection['source']['sha256']===Catalog::owned('product_info_versions',$label,$p)['snapshot_sha256']);
ok('Batch expiry has producer provenance',$projection['expiry']['value']==='2027-01-10'&&$projection['expiry']['source']==='producer');
$labelData['version_key']='C2';$labelData['food_data']['nutrition']['values']['carbohydrate_g']=8;$new=Catalog::label($p,$item,$labelData)['id'];Catalog::publishLabel($p,$new);
ok('Historical batch keeps original nutrition',ConsumerFood::lookup(url('/b/'.$lot))['food_data']['nutrition']['values']['carbohydrate_g']===4.2);
ok('Generic product gets new approved version',ConsumerFood::lookup($gtin)['food_data']['nutrition']['values']['carbohydrate_g']===8.0);
Catalog::alert($p,$lot,['message'=>'Retragere de probă.','state'=>'recalled']);
$old=ConsumerFood::lookup(url('/b/'.$lot));ok('Current recall overlays old facts',$old['batch_state']==='recalled'&&count($old['alerts'])===1&&$old['source']['version']==='C1');
$generic=ConsumerFood::lookup($gtin);ok('Generic product warns about affected lots',count($generic['alerts'])===1&&$generic['alert_scope']==='product_only');
$unknownLot=ConsumerFood::lookup('https://example.org/01/'.DigitalLink::gtin($gtin).'/10/UNKNOWN');ok('Unknown lot is not replaced with an affected lot',$unknownLot['batch_id']===null&&$unknownLot['lot_code']==='UNKNOWN'&&$unknownLot['alerts']===[]);
ok('Public projection has no tenant or credentials',!preg_match('/tenant_id|password|token_hash|claim_evidence/',Db::json($projection)));
$uri=\App\Domain\ResolverUri::parse('/01/'.DigitalLink::gtin($gtin));$set=\App\Domain\Resolver::links($uri);$uri['parameters']['linkType']='gs1:masterData';
$choice=\App\Domain\Resolver::choose($uri,$set,'application/json','');ok('Legacy masterData negotiation remains compatible',str_contains($choice['link']['href'],'/api/v1/'));
$uri['parameters']['context']=url('/api/schemas/consumer-product-profile.schema.json');$choice=\App\Domain\Resolver::choose($uri,$set,'application/json','');ok('Resolver discovers versioned consumer profile',str_contains($choice['link']['href'],'/api/v2/public/food?'));
ok('Pinned OCR resources installed locally',ConsumerAssets::ready());
file_put_contents(ROOT.'/tests/runtime/consumer-fixtures.json',Db::json(['gtin'=>$gtin,'trade_item'=>$item,'batch'=>$lot,'label'=>$label]));
file_put_contents(ROOT.'/tests/runtime/reports/consumer-domain-report.json',Db::json(['executed_at'=>gmdate(DATE_ATOM),'environment'=>'isolated MariaDB/PHP','passed'=>count($checks),'failed'=>0,'checks'=>$checks]));
echo Db::json(['passed'=>count($checks),'failed'=>0]).PHP_EOL;
